package firejail

import "strconv"

// HeaderLine is the first line of every file Jailcat generates (SPEC §9): the profile
// starts with it, the launcher script and the desktop entry carry it as a comment. A
// file that lacks it was not made by Jailcat.
const HeaderLine = "# Generated by Jailcat. Do not edit: change it in Jailcat and rebuild."

// buildMarkerPrefix starts the second header line, which names the build.
const buildMarkerPrefix = "# jailcat-build: "

// BuildLine returns the second header line of a generated file (SPEC §9): the id of the
// build that made it.
func BuildLine(buildID int64) string {
	return buildMarkerPrefix + strconv.FormatInt(buildID, 10)
}

// Header returns the two header lines of SPEC §9 for a build, without line endings:
// [HeaderLine] and [BuildLine]. The profile writer uses it, and so does the launcher
// script (step 2.4), which puts them after its "#!" line.
func Header(buildID int64) []string {
	return []string{HeaderLine, BuildLine(buildID)}
}
